   621   *
   622   * Returns the amount of char read, or -1 in case of error, 0 indicate the
   623   * end of this entity
   624   */
   625  int
   626  xmlParserInputGrow(xmlParserInputPtr in, int len) {
   627      int ret;
   628      size_t indx;
   629
   630      if ((in == NULL) || (len < 0)) return(-1);
   631      if (in->buf == NULL) return(-1);
   632      if (in->base == NULL) return(-1);
   633      if (in->cur == NULL) return(-1);
   634      if (in->buf->buffer == NULL) return(-1);
   635
   636      indx = in->cur - in->base;
   637      if (xmlBufUse(in->buf->buffer) > (unsigned int) indx + INPUT_CHUNK) {
   638          return(0);
   639      }
   640      ret = xmlParserInputBufferGrow(in->buf, len);
   641
   642      in->base = xmlBufContent(in->buf->buffer);
   643      if (in->base == NULL) {
   644          in->base = BAD_CAST "";
   645          in->cur = in->base;
   646          in->end = in->base;
   647          return(-1);
   648      }
   649      in->cur = in->base + indx;
   650      in->end = xmlBufEnd(in->buf->buffer);
   651
   652      return(ret);
